-- REEMISION DE LOS CODIGOS DEL ENVIO 265
--
-- El 19-nov el envio 265 salio con la plantilla del cupon del 50% pero sin
-- oferta seleccionada: 500 personas recibieron el correo con los comodines
-- vacios -sin nombre, sin codigo, sin fecha- y NO se emitio ningun codigo.
--
-- Aqui se les emite el codigo que les correspondia y se les vuelve a escribir.
--
-- SE ATAN AL MISMO idenvio 265 a proposito: asi la campana queda medible como
-- cualquier otra (oferta_cliente.idenvio es lo que separa cada tanda) en vez
-- de dejar 499 codigos huerfanos.
--
-- 499 y no 500: la persona 267618 no tiene ninguna
-- fila de cliente ligada, y sin cliente no se puede emitir. Es la misma regla
-- del sistema: antes que mandar un correo que promete un descuento sin codigo,
-- no se manda.
--
-- fecha_caducidad = 2026-11-21: la promo era 19 y 20, pero estas personas
-- perdieron el 19 por nuestro error, asi que se les repone el dia.
--
-- Idempotente: si ya se corrio, no vuelve a insertar.

SET @ya := (SELECT count(*) FROM pizzaamericana.oferta_cliente
             WHERE idenvio = 265 AND idoferta = 61);
SELECT IF(@ya > 0, CONCAT('YA SE HABIA CORRIDO: ', @ya, ' codigos. No se inserta nada.'),
                   'Sin codigos previos, se procede.') AS control;

INSERT INTO pizzaamericana.oferta_cliente
      (idoferta, idcliente, utilizada, PQRS, ingreso_oferta, usuario_ingreso,
       observacion, codigo_promocion, fecha_caducidad, saldo, cliente, idenvio, anulada)
SELECT * FROM (
  SELECT 61 AS idoferta, 858854 AS idcliente, 'N' AS utilizada, 0 AS pqrs, now() AS ingreso_oferta, 'jdbotero' AS usuario_ingreso, 'Reemision: el envio 265 salio sin codigo' AS observacion, 'ZSWCV36L' AS codigo_promocion, '2026-11-21' AS fecha_caducidad, 0 AS saldo, '' AS cliente, 265 AS idenvio, 'N' AS anulada UNION ALL
